import {callTool, listTools} from "./server.mjs";

const checks = [];

// 1. normal batch with a missing user, request order preserved
let r = await callTool("users_get_many", {user_ids:["u3","u2","missing"]});
checks.push(["order+missing", r.content[0].text === "u3: Edsger\nu2: Grace\nmissing: <missing>"]);

// 2. duplicate ids rejected
try { await callTool("users_get_many", {user_ids:["u1","u1"]}); checks.push(["dup", false]); }
catch (e) { checks.push(["dup", /duplicate/i.test(e.message)]); }

// 3. empty array rejected
try { await callTool("users_get_many", {user_ids:[]}); checks.push(["empty", false]); }
catch (e) { checks.push(["empty", /non-empty/i.test(e.message)]); }

// 4. more than 5 entries rejected
try { await callTool("users_get_many", {user_ids:["a","b","c","d","e","f"]}); checks.push(["max", false]); }
catch (e) { checks.push(["max", /at most 5/i.test(e.message)]); }

// 5. non-array rejected
try { await callTool("users_get_many", {user_ids:"u1"}); checks.push(["nonarray", false]); }
catch (e) { checks.push(["nonarray", /array/i.test(e.message)]); }

// 6. extra field rejected
try { await callTool("users_get_many", {user_ids:["u1"], extra:1}); checks.push(["extra", false]); }
catch (e) { checks.push(["extra", /unexpected/i.test(e.message)]); }

// 7. unknown tool rejected
try { await callTool("nope", {}); checks.push(["unknown", false]); }
catch (e) { checks.push(["unknown", /unknown tool/i.test(e.message)]); }

// 8. non-string entry rejected
try { await callTool("users_get_many", {user_ids:[1]}); checks.push(["nonstring", false]); }
catch (e) { checks.push(["nonstring", /non-empty string/i.test(e.message)]); }

// 9. empty string entry rejected
try { await callTool("users_get_many", {user_ids:[""]}); checks.push(["emptystr", false]); }
catch (e) { checks.push(["emptystr", /non-empty string/i.test(e.message)]); }

// 10. listTools schema has additionalProperties:false
const tools = await listTools();
const s = tools[0].inputSchema;
checks.push(["schema-additionalProperties", s.additionalProperties === false]);
checks.push(["schema-required", Array.isArray(s.required) && s.required[0]==="user_ids"]);
checks.push(["schema-maxItems", s.properties.user_ids.maxItems === 5]);
checks.push(["schema-minItems", s.properties.user_ids.minItems === 1]);
checks.push(["schema-uniqueItems", s.properties.user_ids.uniqueItems === true]);

let ok = true;
for (const [n, p] of checks) { if (!p) ok=false; console.log((p?"PASS":"FAIL"), n); }
console.log(ok ? "ALL PASS" : "SOME FAILED");
process.exit(ok?0:1);
'
"}

